examples.template:
MonarchButton(isDeactivated ? "Reactivate" : {{trigger}}, variant: .warning) { isPresented = true }
    .sheet(isPresented: $isPresented) {
        ScrollView {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                Image(systemName: "exclamationmark.triangle")
                    .font(.system(size: 20))
                    .foregroundStyle(theme.colors.warningStrong)
                    .frame(width: 40, height: 40)
                    .background(theme.colors.warningSubtle, in: RoundedRectangle(cornerRadius: 10))
                    .accessibilityHidden(true)
                Text(isDeactivated ? "Reactivate \(subject)?" : "Deactivate \(subject)?")
                    .monarchTextStyle(.title)
                    .accessibilityAddTraits(.isHeader)
                Text(
                    isDeactivated
                        ? "It starts working again straight away."
                        : "It stops working until you turn it back on. Nothing is deleted."
                )
                .monarchTextStyle(.body)
                if !isDeactivated {
                    Label("You can reactivate it at any time from \(reactivateFrom).", systemImage: "arrow.uturn.backward")
                        .monarchTextStyle(.body)
                }
                MonarchConsequenceList(
                    isDeactivated
                        ? [MonarchConsequence(.changed, "Shared reports update again")]
                        : [
                            MonarchConsequence(.{{consequences.0.kind|raw}}, {{consequences.0.label}}),
                            MonarchConsequence(.{{consequences.1.kind|raw}}, {{consequences.1.label}}),
                            MonarchConsequence(.{{consequences.2.kind|raw}}, {{consequences.2.label}}),
                        ],
                    heading: isDeactivated ? "Once it is reactivated" : "While it is deactivated"
                )
                if asksReason {
                    MonarchTextField("Reason (optional)", text: $reason, helper: "Kept with the change history.")
                }
                if let failure {
                    MonarchInlineNotice(failure, tone: .danger)
                }
                MonarchButton(
                    isDeactivated ? "Reactivate" : {{trigger}},
                    variant: .primary,
                    isLoading: isWorking,
                    fullWidth: true,
                    action: confirm
                )
                MonarchButton("Cancel", variant: .ghost, fullWidth: true) { isPresented = false }
            }
            .padding(theme.spacing.space4)
        }
        .presentationDetents([.medium, .large])
        .interactiveDismissDisabled(isWorking)
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isPresented = false
@State private var isDeactivated = false
@State private var reason = ""
@State private var isWorking = false
@State private var failure: String?

private func confirm() {
    isWorking = true
    failure = nil
    Task {
        // The app's request, with reason. A thrown error goes in failure and the sheet stays open.
        try? await Task.sleep(for: .milliseconds(300))
        isWorking = false
        isDeactivated.toggle()
        isPresented = false
    }
}
private let asksReason = {{reason}}
private let subject = {{subject}}
private let reactivateFrom = {{reactivateFrom}}

